// #bf7c47 (6a993d6cdaed11dfc1bf7c47) — окно «לוג טכני אחרון» при повторном сбое отчёта (S-02, Figma 842:3057), реджект rej_59813d3f.
// Кейсы SUP-010…SUP-013 (SUP-014 — rerun-permissions-bf7c47.spec.ts). Super Admin → /admin/support (все даты) → строка с data-manual-handling=true →
// ⋮ «פעולות תמיכה עבור …» → «הפעלה מחדש של עיבוד»: у строки «לטיפול ידני» это ТОЛЬКО окно с логом (повторно обработку не запускает).
// ЧИТАЕТ ТОЛЬКО: перезапуск обработки не нажимается и не вызывается (проверяем, что rpc admin_rerun_report_processing не уходил).
// Данные: QA-PHONE-17fdd9-0411-A / QA-C10-2110-D3 / QA-CALL1-0411 (первый из них в «לטיפול ידני»). Админка — только десктоп (L-20261014-5).
import { Locator, Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { openSupport, openRowMenu, supportRow, escapeRe } from './support-helpers';

const HASH = '#bf7c47 · #6a993d6cdaed11dfc1bf7c47';
const CANDIDATES = ['QA-PHONE-17fdd9-0411-A', 'QA-C10-2110-D3', 'QA-CALL1-0411'];
const TOL = 0.6; // субпиксель

type Box = { x: number; y: number; w: number; h: number; right: number };
const box = (l: Locator): Promise<Box> =>
  l.evaluate((el) => {
    const r = el.getBoundingClientRect();
    return { x: r.x, y: r.y, w: r.width, h: r.height, right: r.right };
  });

/** Открывает окно лога у первой строки «לטיפול ידני» из списка QA-кандидатов. Следит, чтобы перезапуск не уходил. */
async function openLogDialog(admin: Page) {
  const reruns: string[] = [];
  admin.on('request', (r) => {
    if (r.url().includes('/rpc/admin_rerun_report_processing')) reruns.push(r.url());
  });
  await openSupport(admin);
  const manual = admin
    .locator('[data-testid=support-row][data-manual-handling=true]')
    .filter({ has: admin.locator('td[data-label="מועמד/ת"]', { hasText: new RegExp(`^(${CANDIDATES.map(escapeRe).join('|')})$`) }) });
  await expect(manual.first(), `нет строки «לטיפול ידני» ни у одного из ${CANDIDATES.join(', ')} — нет данных`).toBeVisible({ timeout: 40_000 });
  let name = '';
  for (const n of CANDIDATES) {
    if ((await manual.filter({ has: admin.locator('td[data-label="מועמד/ת"]', { hasText: new RegExp(`^${escapeRe(n)}$`) }) }).count()) > 0) {
      name = n;
      break;
    }
  }
  expect(name, 'не нашли кандидата со строкой «לטיפול ידני»').not.toBe('');
  const row = supportRow(admin, name);
  // Страховка: пункт «הפעלה מחדש של עיבוד» безопасен только у строки «לטיפול ידני» (там он открывает лишь окно с логом).
  await expect(row).toHaveAttribute('data-manual-handling', 'true');
  await expect(row).toHaveAttribute('data-report-status', 'generation_error');
  await openRowMenu(admin, name);
  await admin.getByRole('menuitem', { name: 'הפעלה מחדש של עיבוד', exact: true }).click();
  const dialog = admin.getByTestId('support-rerun-log');
  await expect(dialog).toBeVisible();
  await expect(dialog.getByText('לוג טכני אחרון', { exact: true })).toBeVisible();
  return { dialog, name, reruns };
}

test.describe(`Поддержка — окно «לוג טכני אחרון» при повторном сбое (${HASH})`, () => {
  test(`окно открывается без формы и без запуска обработки; в нём заголовок, баннер, лог и две кнопки @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const admin = await asUser('admin');
    await admin.setViewportSize({ width: 1440, height: 900 });
    const { dialog, name, reruns } = await openLogDialog(admin);

    // Источник: AC3 «הרשומה מסומנת לטיפול ידני ומוצג הלוג הטכני האחרון».
    await expect(dialog.getByText('הפעלה מחדש של עיבוד', { exact: true }).first()).toBeVisible();
    await expect(dialog.getByText(name).first()).toBeVisible();
    await expect(dialog.getByText('כשל חוזר: הרשומה סומנה לטיפול ידני')).toBeVisible();
    await expect(dialog.locator('button', { hasText: /^סגירה$/ })).toBeVisible();
    await expect(dialog.locator('button', { hasText: 'העתקת הלוג' })).toBeVisible();
    // Только чтение: нет формы причины/подтверждения, запрос на перезапуск не уходил.
    await expect(dialog.getByRole('textbox', { name: 'סיבת הפעולה' })).toHaveCount(0);
    expect(reruns, 'rpc admin_rerun_report_processing не должен вызываться').toEqual([]);
  });

  test(`строка лога: одна строка 500×20, LTR, прижата к началу, формат «HH:MM:SS report-processing failed (attempt N of 2): …» @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const admin = await asUser('admin');
    await admin.setViewportSize({ width: 1440, height: 900 });
    const { dialog } = await openLogDialog(admin);

    const lines = dialog.getByTestId('support-log-line');
    expect(await lines.count(), 'в окне есть строки лога').toBeGreaterThan(0);
    for (let i = 0; i < (await lines.count()); i++) {
      const line = lines.nth(i);
      const b = await box(line);
      // Источник: реджект rej_59813d3f п.1 — Figma 842:3057: строка 500×20, одна строка, LTR, text-align left.
      expect(b.w, `строка ${i + 1}: ширина`).toBeGreaterThanOrEqual(500 - TOL);
      expect(b.w, `строка ${i + 1}: ширина`).toBeLessThanOrEqual(500 + TOL);
      expect(b.h, `строка ${i + 1}: высота (одна строка, не две)`).toBeGreaterThanOrEqual(20 - TOL);
      expect(b.h, `строка ${i + 1}: высота (одна строка, не две)`).toBeLessThanOrEqual(20 + TOL);
      await expect(line).toHaveAttribute('dir', 'ltr');
      const css = await line.evaluate((el) => {
        const s = getComputedStyle(el);
        return { direction: s.direction, textAlign: s.textAlign };
      });
      expect(css.direction).toBe('ltr');
      expect(['left', 'start'], `text-align: ${css.textAlign}`).toContain(css.textAlign);
      // Формат кадра: время (не дата), «of N», причина через дефисы.
      await expect(line).toHaveText(/^\d{2}:\d{2}:\d{2}\s+report-processing\s+failed \(attempt \d of 2\): \S+/);
    }
  });

  test(`кнопки: «סגירה» 160×52, «העתקת הלוג» высотой 52, зазор между ними 16 @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const admin = await asUser('admin');
    await admin.setViewportSize({ width: 1440, height: 900 });
    const { dialog } = await openLogDialog(admin);

    const close = await box(dialog.locator('button', { hasText: /^סגירה$/ }));
    const copy = await box(dialog.locator('button', { hasText: 'העתקת הלוג' }));
    // Источник: реджект rej_59813d3f п.2–3 (Figma 842:3057). Ширина «העתקת הלוג» зависит от шрифта (#82fb2b) — не сверяем.
    expect(close.w, '«סגירה» ширина').toBeGreaterThanOrEqual(160 - TOL);
    expect(close.w, '«סגירה» ширина').toBeLessThanOrEqual(160 + TOL);
    expect(close.h, '«סגירה» высота').toBeGreaterThanOrEqual(52 - TOL);
    expect(close.h, '«סגירה» высота').toBeLessThanOrEqual(52 + TOL);
    expect(copy.h, '«העתקת הלוג» высота').toBeGreaterThanOrEqual(52 - TOL);
    expect(copy.h, '«העתקת הלוג» высота').toBeLessThanOrEqual(52 + TOL);
    const gap = Math.min(Math.abs(close.x - copy.right), Math.abs(copy.x - close.right));
    expect(gap, 'зазор между кнопками').toBeGreaterThanOrEqual(16 - TOL);
    expect(gap, 'зазор между кнопками').toBeLessThanOrEqual(16 + TOL);
  });

  test(`крестик закрытия 40×40, иконка 20×20 по центру (10,10) @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const admin = await asUser('admin');
    await admin.setViewportSize({ width: 1440, height: 900 });
    const { dialog } = await openLogDialog(admin);

    const x = dialog.getByTestId('dialog-close');
    const b = await box(x);
    // Источник: реджект rej_59813d3f п.4 — × 40×40 (зона нажатия 44 — через ::before, не замеряем).
    expect(b.w, '× ширина').toBeGreaterThanOrEqual(40 - TOL);
    expect(b.w, '× ширина').toBeLessThanOrEqual(40 + TOL);
    expect(b.h, '× высота').toBeGreaterThanOrEqual(40 - TOL);
    expect(b.h, '× высота').toBeLessThanOrEqual(40 + TOL);
    const icon = await box(x.locator('img').first());
    expect(icon.w, 'иконка ×: ширина').toBeCloseTo(20, 0);
    expect(icon.h, 'иконка ×: высота').toBeCloseTo(20, 0);
    expect(icon.x - b.x, 'иконка: отступ слева').toBeGreaterThanOrEqual(10 - TOL);
    expect(icon.x - b.x, 'иконка: отступ слева').toBeLessThanOrEqual(10 + TOL);
    expect(icon.y - b.y, 'иконка: отступ сверху').toBeGreaterThanOrEqual(10 - TOL);
    expect(icon.y - b.y, 'иконка: отступ сверху').toBeLessThanOrEqual(10 + TOL);

    // Закрытие крестиком — окно уходит, адрес прежний.
    await x.click();
    await expect(dialog).toBeHidden();
    await expect(admin).toHaveURL(/\/admin\/support/);
  });
});
